'use strict';
(()=>{
const variants=['live','remix','acoustic','instrumental','karaoke','demo','cover'];
const normalize=s=>String(s||'').normalize('NFKD').replace(/\p{M}/gu,'').toLowerCase().replace(/[^\p{L}\p{N}]+/gu,' ').trim().replace(/\s+/g,' ');
function coverage(wanted,text){const words=normalize(wanted).split(' ').filter(Boolean),available=new Set(normalize(text).split(' '));return words.length?words.filter(w=>available.has(w)).length/words.length:0}
function quality(text){const raw=String(text||'');const compact=/\b(16|24|32)[/_-](44(?:\.1)?|48|88(?:\.2)?|96|176(?:\.4)?|192)\b/.exec(raw);const bits=/(?:^|[^0-9])(24|32)\s*[- ]?bit/i.exec(raw);const rate=/(192|176(?:\.4)?|96|88(?:\.2)?|48|44(?:\.1)?)\s*k(?:hz)?/i.exec(raw);return Number(bits?.[1]||compact?.[1]||16)*1000+Number(rate?.[1]||compact?.[2]||44)}
function versionTags(text){const s=String(text||'').toLowerCase(),set=new Set();for(const v of ['remix','acoustic','instrumental','karaoke','demo'])if(new RegExp('\\b'+v+'\\b').test(s))set.add(v);if(/(?:[([]|[-–]\s*)live\b|\blive\s+(?:at|from|in|on)\b/.test(s))set.add('live');if(/\b(?:cover version|tribute)\b/.test(s))set.add('cover');return set}
function variantMatch(track,text){const wanted=versionTags(track.title+' '+track.album),actual=versionTags(text);return variants.every(v=>wanted.has(v)===actual.has(v))}
function rankReleases(releases,track,limit=3){return releases.filter(r=>/^[a-f\d]{40}$/i.test(r.hash||'')&&(coverage(track.artist,r.title)>=.8||(/\b(?:various artists|va)\b/i.test(r.title)&&coverage(track.album,r.title)>=.9))&&variantMatch(track,r.title)).map(r=>({...r,rank:coverage(track.album,r.title)*100000+quality(r.title)+(Number(r.seeders)||0)/1000})).sort((a,b)=>b.rank-a.rank).slice(0,limit)}
function cleanTitle(text){return normalize(String(text||'').replace(/\((?:feat|featuring|ft)\.?[^)]*\)|\[(?:feat|featuring|ft)\.?[^\]]*\]/gi,'').replace(/[([]\s*(?:(?:19|20)\d{2}\s*)?(?:remaster(?:ed)?|album version)(?:\s*(?:19|20)\d{2})?\s*[)\]]/gi,'').replace(/\s*[-–]\s*(?:(?:19|20)\d{2}\s*)?remaster(?:ed)?(?:\s*(?:19|20)\d{2})?\s*$/i,''))}
function stripNumber(text,title){text=text.replace(/^\s*cd\s*\d+[-_. ]+/i,'');for(let i=0;i<2;i++){if(title&&cleanTitle(text)===title)break;const next=text.replace(/^\s*[([]?\d{1,3}[)\]]?[-_. ]+/,'');if(next===text)break;text=next}return text}
function cleanedFile(filename,artist,album,title){let text=String(filename).replace(/\.[^.]+$/,'').replace(/[([][^)\]]*(?:flac|mp3|aac|alac|\d\s*bit|\d\s*k(?:hz|bps)|(?:16|24|32)[/-](?:44|48|88|96|176|192))[^)\]]*[)\]]/gi,'');text=cleanTitle(stripNumber(text,title)).replace(/\b(?:feat|featuring|ft)\b.*$/,'').trim();for(const prefix of [artist,album,artist]){const p=normalize(prefix);if(p&&text.startsWith(p+' '))text=normalize(stripNumber(text.slice(p.length+1),title))}return normalize(stripNumber(text,title))}
function codec(filename){const ext=String(filename||'').match(/\.(flac|wav|aiff|aif|mp3|m4a|aac|ogg|opus)$/i)?.[1]?.toUpperCase();return ext?{name:ext,lossless:/^(FLAC|WAV|AIFF|AIF)$/.test(ext)}:null}
function matchFiles(files,release,track,{allowLossy=false}={}){const title=cleanTitle(track.title);return files.filter(f=>{const c=codec(f.filename);return c&&(c.lossless||allowLossy)&&cleanedFile(f.filename,track.artist,track.album,title)===title&&variantMatch(track,f.filename+' '+release.title+' '+(f.path||''))&&coverage(track.artist,release.title+' '+(f.path||'')+' '+f.filename)>=.8}).map(f=>{const c=codec(f.filename),text=release.title+' '+f.path+' '+f.filename,bitrate=Number(text.match(/\b(320|256|192|160|128|96)\s*(?:kbps|k)\b/i)?.[1]||0);return {...f,sourceCodec:c.name,losslessCandidate:c.lossless,rank:(c.lossless?1000000+quality(text):bitrate),release:release.title}}).sort((a,b)=>b.rank-a.rank)}
window.MonoMatch={normalize,coverage,quality,rankReleases,matchFiles,codec};
})();
